async def act(page):
    import urllib.parse
    import asyncio

    # 1) Navigate to the visible "Sample Page" (relative goto preferred)
    sample_locator = page.get_by_role("link", name="Sample Page")
    if await sample_locator.count() == 0:
        # No Sample Page link visible from current state; cannot proceed.
        return

    try:
        sample_href = await sample_locator.first().get_attribute("href")
    except Exception:
        sample_href = None

    if not sample_href:
        return

    parsed_sample = urllib.parse.urlparse(sample_href)
    if parsed_sample.netloc == "":
        await page.goto(sample_href)
    else:
        await page.goto(sample_href)

    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        pass
    await asyncio.sleep(0.4)

    # 2) Try to find the post link by accessible-name heuristics
    target_candidates = [
        "How to get rid of unwanted Christmas presents - without being found out",
        "How to get rid of unwanted Christmas presents",
        "unwanted Christmas presents",
        "Christmas presents",
        "How to get rid of unwanted",
    ]

    post_href = None
    for name in target_candidates:
        locator = page.get_by_role("link", name=name)
        try:
            if await locator.count() > 0:
                post_href = await locator.first().get_attribute("href")
        except Exception:
            post_href = None
        if post_href:
            break

    # 3) Broad fallback: scan all links for 'christmas' in their accessible name
    if not post_href:
        all_links = page.get_by_role("link")
        total = await all_links.count()
        for i in range(total):
            try:
                text = (await all_links.nth(i).inner_text()).strip()
            except Exception:
                text = ""
            if "christmas" in text.lower():
                try:
                    post_href = await all_links.nth(i).get_attribute("href")
                except Exception:
                    post_href = None
                if post_href:
                    break

    if not post_href:
        # Could not locate the target post link from Sample Page; stop.
        return

    # 4) Navigate to the post page (relative goto when possible)
    parsed_post = urllib.parse.urlparse(post_href)
    if parsed_post.netloc == "":
        await page.goto(post_href)
    else:
        await page.goto(post_href)

    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        pass
    await asyncio.sleep(0.4)

    # 5) Locate the comment textbox (role="textbox") and fill the required comment
    textbox = page.get_by_role("textbox")
    if await textbox.count() == 0:
        # No accessible textbox found; cannot leave comment reliably.
        return

    # Fill the primary comment field (heuristic: first textbox)
    await textbox.nth(0).fill("Interesting perspective.")

    # 6) Heuristically fill name/email if additional textboxes exist (best-effort)
    tb_count = await textbox.count()
    if tb_count >= 2:
        try:
            await textbox.nth(1).fill("Playwright Tester")
        except Exception:
            pass
    if tb_count >= 3:
        try:
            await textbox.nth(2).fill("tester@example.com")
        except Exception:
            pass

    # 7) Locate a submit button using accessible-name heuristics and fall back to any button.
    submit_btn = None
    candidate_buttons = [
        page.get_by_role("button", name="Post Comment"),
        page.get_by_role("button", name="Submit Comment"),
        page.get_by_role("button", name="Post"),
        page.get_by_role("button", name="Submit"),
        page.get_by_role("button", name="Comment"),
    ]
    for cand in candidate_buttons:
        try:
            if await cand.count() > 0:
                submit_btn = cand.first()
                break
        except Exception:
            continue

    if submit_btn is None:
        any_btn = page.get_by_role("button")
        if await any_btn.count() > 0:
            submit_btn = any_btn.first()

    # 8) Click the submit button as the final action (it may navigate away / submit the form).
    if submit_btn is not None:
        await submit_btn.click()

    return

